"""Polynomial and calculus helper module."""

import math


def _is_number(x):
    return isinstance(x, (int, float))

class Polynomial:
    """Polynomial represented by a list of coefficients in ascending order."""

    def __init__(self, coeffs):
        """
        Initialize polynomial with coefficients.

        Args:
            coeffs (list of numbers): Coefficients in ascending order (constant first).
        """
        if not all(_is_number(c) for c in coeffs):
            raise ValueError("All coefficients must be numbers.")
        # Remove trailing zeros
        while len(coeffs) > 1 and coeffs[-1] == 0:
            coeffs.pop()
        self.coeffs = coeffs

    def degree(self):
        """Return degree of polynomial."""
        return len(self.coeffs) - 1

    def __repr__(self):
        return f"Polynomial({self.coeffs})"

    def __str__(self):
        return self.pretty()

    def pretty(self):
        """Pretty print polynomial in human-readable form."""
        terms = []
        for i, c in enumerate(self.coeffs):
            if c == 0:
                continue
            if i == 0:
                terms.append(str(c))
            else:
                if c == 1:
                    terms.append(f"x^{i}" if i > 1 else "x")
                elif c == -1:
                    terms.append(f"-x^{i}" if i > 1 else "-x")
                else:
                    terms.append(f"{c}*x^{i}" if i > 1 else f"{c}*x")
        if not terms:
            return "0"
        return " + ".join(terms).replace("+ -", "- ")

    def __add__(self, other):
        """Add two polynomials."""
        if not isinstance(other, Polynomial):
            return NotImplemented
        max_len = max(len(self.coeffs), len(other.coeffs))
        result = [0] * max_len
        for i in range(max_len):
            c1 = self.coeffs[i] if i < len(self.coeffs) else 0
            c2 = other.coeffs[i] if i < len(other.coeffs) else 0
            result[i] = c1 + c2
        return Polynomial(result)

    def __sub__(self, other):
        """Subtract two polynomials."""
        if not isinstance(other, Polynomial):
            return NotImplemented
        max_len = max(len(self.coeffs), len(other.coeffs))
        result = [0] * max_len
        for i in range(max_len):
            c1 = self.coeffs[i] if i < len(self.coeffs) else 0
            c2 = other.coeffs[i] if i < len(other.coeffs) else 0
            result[i] = c1 - c2
        return Polynomial(result)

    def __mul__(self, other):
        """Multiply two polynomials."""
        if not isinstance(other, Polynomial):
            return NotImplemented
        result = [0] * (len(self.coeffs) + len(other.coeffs) - 1)
        for i, c1 in enumerate(self.coeffs):
            for j, c2 in enumerate(other.coeffs):
                result[i+j] += c1 * c2
        return Polynomial(result)

    def __call__(self, x):
        """Evaluate polynomial at given x."""
        result = 0
        power = 1
        for c in self.coeffs:
            result += c * power
            power *= x
        return result

    def derivative(self):
        """Return the derivative polynomial."""
        if len(self.coeffs) <= 1:
            return Polynomial([0])
        deriv = [i * c for i, c in enumerate(self.coeffs)][1:]
        return Polynomial(deriv)

    def integral(self, constant=0):
        """Return the indefinite integral polynomial with constant term."""
        integ = [constant] + [self.coeffs[i] / (i+1) for i in range(len(self.coeffs))]
        return Polynomial(integ)

    def find_root_newton(self, start, tolerance=1e-7, max_iter=1000):
        """
        Find a root using Newton's method.

        Args:
            start (float): Initial guess.
            tolerance (float): Convergence tolerance.
            max_iter (int): Maximum iterations.

        Returns:
            float or None: Root found or None if no convergence.
        """
        x = start
        deriv = self.derivative()
        for _ in range(max_iter):
            fx = self(x)
            dfx = deriv(x)
            if abs(fx) < tolerance:
                return x
            if dfx == 0:
                return None
            x = x - fx / dfx
        return None

    def find_root_bisection(self, a, b, tolerance=1e-7, max_iter=1000):
        """
        Find root using bisection method.

        Args:
            a (float): Start interval.
            b (float): End interval.
            tolerance (float): Convergence tolerance.
            max_iter (int): Maximum iterations.

        Returns:
            float or None: Root found or None if no root in interval.
        """
        fa = self(a)
        fb = self(b)
        if fa * fb > 0:
            return None
        for _ in range(max_iter):
            c = (a + b) / 2
            fc = self(c)
            if abs(fc) < tolerance or abs(b - a) / 2 < tolerance:
                return c
            if fc * fa > 0:
                a, fa = c, fc
            else:
                b = c
        return None


